import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";
import { FaHome, FaUser, FaCar, FaCreditCard, FaCheckCircle } from "react-icons/fa";

function HomePage() {
  const navigate = useNavigate();

  const menuItems = [
    { name: "Home", icon: <FaHome />, action: () => navigate("/") },
    { name: "Profile", icon: <FaUser />, action: () => navigate("/profile") },
    { name: "Bookings", icon: <FaCar />, action: () => navigate("/booking") },
    { name: "Payment", icon: <FaCreditCard />, action: () => navigate("/payment") },
    { name: "Success", icon: <FaCheckCircle />, action: () => navigate("/success") },
  ];

  return (
    <div className="homepage-container">
      {/* Navbar */}
      <nav className="navbar">
        <div className="navbar-logo">🚗 Parking Slot System</div>
        <div className="navbar-links">
          {menuItems.map((item, index) => (
            <button key={index} className="nav-btn" onClick={item.action}>
              {item.name}
            </button>
          ))}
          <button
            className="logout-btn"
            onClick={() => {
              localStorage.removeItem("user");
              navigate("/login");
            }}
          >
            Logout
          </button>
        </div>
      </nav>

      {/* Sidebar */}
      <aside className="sidebar">
        {menuItems.map((item, index) => (
          <button key={index} className="sidebar-btn" onClick={item.action}>
            <span className="sidebar-icon">{item.icon}</span>
            <span className="sidebar-text">{item.name}</span>
          </button>
        ))}
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <div className="welcome-card">
          <h1>Welcome to the Parking Slot Booking System</h1>
          <p>Efficiently book your parking slots with ease. Use the sidebar or navbar to navigate.</p>
        </div>
      </main>
    </div>
  );
}

export default HomePage;
